SELECT *
FROM shopwizard.tOrdOrderUprice

    AND ShopCode = #{pShopCode}
    AND MatchUpriceCode LIKE CONCAT('%',#{pMatchUpriceCode},'%')
    AND OrderProdName LIKE CONCAT('%',#{pOrderProdName},'%')
    AND Keywrd LIKE CONCAT('%',#{pKeywrd},'%')
    AND Capa = #{pCapa}
    AND UseYn = #{pUseYn}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderUprice

    AND ShopCode = #{pShopCode}
    AND MatchUpriceCode LIKE CONCAT('%',#{pMatchUpriceCode},'%')
    AND OrderProdName LIKE CONCAT('%',#{pOrderProdName},'%')
    AND Keywrd LIKE CONCAT('%',#{pKeywrd},'%')
    AND Capa = #{pCapa}
    AND UseYn = #{pUseYn}

SELECT * FROM shopwizard.tOrdOrderUprice

    AND MatchUpriceCode = #{matchUpriceCode}
    AND MatchUpriceCode != #{pMatchUpriceCode}
    AND OrderProdName = #{pOrderProdName}
    AND UseYn = #{pUseYn}
